    /* Array get C# P/Invoke: object_get_motion */
    private static extern /*List<Transform>*/ IntPtr call_object_get_motion(
        IntPtr ptr,
        out int count);

    /* Array get C# wrapper: object_get_motion */
    public static List<Transform> object_get_motion(
        IntPtr ptr
    )
    {
        
        IntPtr data = call_object_get_motion(ptr, out int count);
        int datumSize = Marshal.SizeOf<Transform>();
        int totalSize = datumSize * count;
        byte[] bytedata = new byte[totalSize];
        Marshal.Copy(data, bytedata, 0, totalSize);
        ReadOnlySpan<byte> byteSpan = new ReadOnlySpan<byte>(bytedata);
        ReadOnlySpan<Transform> xSpan = MemoryMarshal.Cast<byte, Transform>(byteSpan);
        var list = new List<Transform>(xSpan.ToArray());
        return list;

    }

